class Solution:
    def doesValidArrayExist(self, derived: list[int]) -> bool:
        import functools
        import operator
        return functools.reduce(operator.xor, derived) == 0

class Solution {
public:
    bool doesValidArrayExist(std::vector<int>& derived) {
        int xor_sum = 0;
        for (int x : derived) xor_sum ^= x;
        return xor_sum == 0;
    }
};

class Solution {
    public boolean doesValidArrayExist(int[] derived) {
        int xorSum = 0;
        for (int x : derived) xorSum ^= x;
        return xorSum == 0;
    }
}

var doesValidArrayExist = function(derived) {
    let xorSum = 0;
    for (const x of derived) xorSum ^= x;
    return xorSum === 0;
};
